const f = $json;
return [{ json: {
  leadId: (f['Lead ID'] || '').trim().toUpperCase(),
  apptDate: (f['Appointment Date'] || '').trim(),
  apptTime: (f['Appointment Time'] || '').trim(),
  teamMember: (f['Team Member'] || '').trim(),
  notes: (f['Notes'] || '').trim()
}}];

const booking = $('Normalize Booking').first().json;
const leads = $input.all().map(i => i.json);
const lead = leads.find(r => String(r['Lead ID'] || '').trim().toUpperCase() === booking.leadId);
if (!lead) {
  return [{ json: { found: false, leadId: booking.leadId, apptDate: booking.apptDate, apptTime: booking.apptTime, teamMember: booking.teamMember, notes: booking.notes } }];
}
return [{ json: {
  found: true,
  leadId: lead['Lead ID'],
  firstName: lead['First Name'] || '',
  lastName: lead['Last Name'] || '',
  phone: lead['Phone'] || '',
  address: lead['Address'] || '',
  serviceNeeded: lead['Service Needed'] || '',
  apptDate: booking.apptDate,
  apptTime: booking.apptTime,
  teamMember: booking.teamMember,
  notes: booking.notes
}}];

const CONFIG = {
  DEFAULT_TIMEZONE: 'America/New_York',
  BUSINESS_START_HOUR: 8,
  BUSINESS_END_HOUR: 17,
  APPOINTMENT_INCREMENT_MINUTES: 30
};

const d = $json;
const apptId = 'APT-' + DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE).toFormat('yyyyMMddHHmmss');
const name = [d.firstName, d.lastName].filter(Boolean).join(' ');
const svcDisplay = d.serviceNeeded || 'roofing appointment';

// Normalize phone to E.164 for Twilio
const raw = String(d.phone || '').replace(/\D/g, '');
const e164 = raw.length === 11 && raw.startsWith('1') ? '+' + raw
  : raw.length === 10 ? '+1' + raw : null;

// Friendly display date for customer-facing SMS (Appt Date is stored as YYYY-MM-DD for machine parsing by reminder workflow)
function formatFriendlyDate(ymd) {
  const m = String(ymd || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return ymd;
  const dt = DateTime.fromObject({ year: +m[1], month: +m[2], day: +m[3] }, { zone: CONFIG.DEFAULT_TIMEZONE });
  return dt.toFormat('cccc, LLLL d');
}
const apptDateDisplay = formatFriendlyDate(d.apptDate);

// Static personalized confirmation SMS
const greeting = d.firstName ? 'Hi ' + d.firstName + ',' : 'Hi,';
const smsText = greeting + ' your ' + svcDisplay + ' appointment with Valfin Tech is confirmed for ' + apptDateDisplay + ' at ' + d.apptTime + '. Questions? Call us anytime.';

return [{ json: {
  apptId,
  leadId: d.leadId,
  customerName: name,
  phone: d.phone,
  e164Phone: e164,
  address: d.address,
  serviceNeeded: d.serviceNeeded,
  apptDate: d.apptDate,
  apptDateDisplay,
  apptTime: d.apptTime,
  teamMember: d.teamMember,
  notes: d.notes,
  smsText
}}];

const d = $('Build Booking Payload').first().json;
return [{ json: {
  leadId: d.leadId,
  status: 'Booked',
  assignedTo: d.teamMember,
  logChannel: 'Phone',
  logDirection: 'Outbound',
  logHandler: 'System',
  logSummary: 'Appointment booked — ' + d.apptDate + ' at ' + d.apptTime,
  logNotes: d.apptId + '. Confirmation SMS sent: ' + d.smsText
}}];
